INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Objektidiagramm nur für statische Strukturen gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Zeigt Laufzeitinstanzen"}, {"text": "Ja", "correct": false, "because": "Dynamisch, nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Objektidiagramm?', 3, '[{"text": "Laufzeitinstanzen darstellen", "correct": true, "because": "Zeigt konkrete Objekte"}, {"text": "Code-Optimierung", "correct": false, "because": "Nicht primär"}, {"text": "Datenflussanalyse", "correct": false, "because": "Anderes Diagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Objektidiagramm?', 5, '[{"text": "Objekte", "correct": true, "because": "Konkrete Instanzen"}, {"text": "Beziehungen", "correct": true, "because": "Verknüpfungen zwischen Objekten"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Objektidiagramme zeigen Instanzen. b) Sie ersetzen Klassendiagramme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klassendiagramme sind abstrakt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Objektidiagramm?', 4, '[{"text": "Objektinstanzen", "correct": false, "because": "Kern des Diagramms"}, {"text": "Beziehungen", "correct": false, "because": "Zeigen Verknüpfungen"}, {"text": "UI-Design", "correct": true, "because": "Kein Laufzeitaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Objektidiagramm auch Methoden zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Instanzen, nicht Logik"}, {"text": "Ja", "correct": false, "because": "Klassendiagramm-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für ein Objektidiagramm?', 3, '[{"text": "Objektinstanz", "correct": true, "because": "Zeigt konkrete Daten"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Klassenmethoden", "correct": false, "because": "Klassendiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen zeigt ein Objektidiagramm?', 5, '[{"text": "Konkrete Objekte", "correct": true, "because": "Laufzeitinstanzen"}, {"text": "Objektbeziehungen", "correct": true, "because": "Verknüpfungen darstellen"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Diagramm"}, {"text": "UI-Interaktionen", "correct": false, "because": "Use-Case-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Objektidiagramme sind Laufzeit-spezifisch. b) Sie zeigen Hardwarezuordnung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Objektidiagramm?', 4, '[{"text": "Objekte", "correct": false, "because": "Kern des Diagramms"}, {"text": "Beziehungen", "correct": false, "because": "Zeigen Verknüpfungen"}, {"text": "Methodenaufrufe", "correct": true, "because": "Sequenzdiagramm-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Objektidiagramm nur für Entwickler?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Tester und Analysten nutzen es"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu einem Objektidiagramm?', 4, '[{"text": "Instanzdaten", "correct": true, "because": "Konkrete Werte"}, {"text": "Verknüpfungen", "correct": true, "because": "Zeigen Beziehungen"}, {"text": "Ablaufsequenzen", "correct": false, "because": "Sequenzdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Objektidiagramme nur Klassen zeigen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Instanzen, nicht Klassen"}, {"text": "Ja", "correct": false, "because": "Klassendiagramm-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Objektidiagramm?', 3, '[{"text": "Klarheit der Instanzen", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Technische Details", "correct": false, "because": "Nicht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Objektidiagramme sind UML-Teil. b) Sie zeigen nur abstrakte Strukturen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konkret, nicht abstrakt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Objektidiagramm?', 5, '[{"text": "Laufzeitverständnis", "correct": true, "because": "Zeigt reale Instanzen"}, {"text": "Testfallbasis", "correct": true, "because": "Konkrete Szenarien"}, {"text": "Datenflussanalyse", "correct": false, "because": "Anderes Diagramm"}, {"text": "Hardwarezuordnung", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Objektidiagramm unwichtig?', 3, '[{"text": "Objektzustände", "correct": false, "because": "Kern der Darstellung"}, {"text": "Verknüpfungen", "correct": false, "because": "Zeigen Beziehungen"}, {"text": "UI-Design", "correct": true, "because": "Kein Laufzeitaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Objektidiagramm auch Abläufe?', 3, '[{"text": "Nein", "correct": true, "because": "Statisch, nicht dynamisch"}, {"text": "Ja", "correct": false, "because": "Sequenzdiagramm-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Objektidiagramm für Debugging hilft?', 2, '[{"text": "Ja", "correct": true, "because": "Zeigt Laufzeitdaten"}, {"text": "Nein", "correct": false, "because": "Nützliches Werkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für ein Objektidiagramm?', 4, '[{"text": "Konkretes Objekt", "correct": true, "because": "Zeigt Instanzdaten"}, {"text": "Datenflusslinie", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Klassenmethoden", "correct": false, "because": "Klassendiagramm"}]');
